function finishGame(g,won){if(g.finished||game!==g)return;g.finished=true;g.paused=true;let remaining=g.queue.length,bonus=won?remaining*1850:0;if(won)score(g,bonus);let par=g.initialPigs*1010+g.blocksBroken*95;let stars=won?(1+Number(remaining>=1||g.score>par*1.9)+Number(remaining>=2&&g.score>par*.92)):0;let hadRecord=!!save.stars[g.id];let base=won?(22+g.world*8+stars*14+(g.bossStage?27:0)+(g.bonus?55:0)+(g.eggCollected?22:0)):clamp(5+g.blocksBroken,5,15),coins=Math.round(base*(1+(save.upgrades.fortune||0)*.2)*(hadRecord&&won ? .46 : 1));save.coins+=coins;if(won){save.stars[g.id]=Math.max(save.stars[g.id]||0,stars);save.best[g.id]=Math.max(save.best[g.id]||0,g.score);if(g.id<=60)save.unlocked=Math.max(save.unlocked,Math.min(61,g.id+1));save.totalWins++}save.stats.shots+=g.shots;save.stats.pigs+=g.kills;save.stats.blocks+=g.blocksBroken;if(g.id===1&&g.shots>0)save.tutorialSeen=true;persist();audio.play(won?'win':'fail');if(won){for(let i=0;i<44;i++)burst(g,330+g.rng()*650,125+g.rng()*290,['#f9da94','#fff4df','#9fd9be'],1,3)}let payload={id:g.id,won,score:g.score,stars,kills:g.kills,initialPigs:g.initialPigs,shots:g.shots,initialBirds:g.initialBirds,blocks:g.blocksBroken,time:g.time,coins,egg:g.eggCollected};modalStack=[{type:'result',payload}];renderModal();updateHUD(true)}
function updateCoach(){let g=game;if(!g||save.tutorialSeen||g.id!==1){$('coach').classList.add('hidden');return}let text=g.shots===0?'PULL BACK from the slingshot, then RELEASE to launch. Arrow keys + Space also work.':g.inFlight&&!g.abilityUsed?'NICE SHOT! Click the field or press SPACE now for this bird’s special power.':g.shots<=2?'Tip: aim at a SUPPORT BEAM. Falling blocks can pop pigs for you.':'';$('coach').textContent=text;$('coach').classList.toggle('hidden',!text)}
function updateHUD(force=false){let g=game;if(!g||screen!=='game')return;let I=levelInfo(g.id);$('hudWorld').textContent=(I.bonus?'BONUS VAULT':`WORLD ${I.world+1} • STAGE ${I.part}`)+(I.boss?' • ♛ BOSS':'');$('hudTitle').textContent=I.name;$('hudPigs').textContent=`${g.pigsAlive} / ${g.initialPigs}`;$('pigFill').style.width=`${g.initialPigs?g.pigsAlive/g.initialPigs*100:0}%`;$('hudFocus').textContent=`${Math.floor(g.focus)}%`;$('focusFill').style.width=`${g.focus}%`;$('hudScore').textContent=fmt(g.score);let wind=g.wind,dir=Math.abs(wind)<.1?'·':wind>0?'→':'←';$('windReadout').textContent=`${dir} WIND ${Math.abs(wind)<.1?'CALM':Math.abs(wind).toFixed(1)}  ·  ${DIFF[g.difficulty].label.toUpperCase()}`;
 $('bossHud').classList.toggle('hidden',!g.boss||g.boss.game.dead);if(g.boss&&!g.boss.game.dead){$('bossName').textContent=g.world===4?'♛ KING SNOUT':'♛ '+['DUKE OF DAWN','ADMIRAL BRINE','BARON BARK','GENERAL CINDER'][g.world];$('bossFill').style.width=`${clamp(g.boss.game.hp/g.boss.game.maxHp*100,0,100)}%`}
 let shown=g.inFlight&&g.flyingBird&&!g.flyingBird.game.dead?[g.flyingBird.game.type,...g.queue]:g.queue.slice();$('birdQueue').innerHTML=shown.length?shown.map((type,i)=>`<button class="bird-slot ${i===0?'active':''}" data-action="swapBird" data-index="${g.inFlight?i-1:i}" ${g.inFlight&&i===0?'disabled':''} title="${BIRDS[type].name} — ${BIRDS[type].skill}">${birdIcon(type)}<span>${i===0?'NOW':String(i+1)}</span></button>`).join(''):'<span style="color:#adbaad;font-size:11px">No birds left</span>';
 $('shotCounter').textContent=`· ${g.shots} FIRED`;
 let active=g.inFlight&&g.flyingBird&&!g.flyingBird.game.dead?g.flyingBird.game.type:g.queue[0],meta=BIRDS[active];$('abilitySigil').textContent=meta?meta.sigil:'✦';$('abilityName').textContent=meta?meta.skill:'FLIGHT ABILITY';$('abilityHint').textContent=g.inFlight?(g.abilityUsed?'USED THIS FLIGHT':'SPACE / TAP TO ACTIVATE'):'SPACE / TAP IN FLIGHT';$('abilityButton').disabled=!g.inFlight||g.abilityUsed||g.paused||g.finished;$('furyButton').disabled=g.focus<100||g.paused||g.finished;$('furyButton').classList.toggle('ready',g.focus>=100);$('flightInstructions').innerHTML=g.inFlight?'Tap the battlefield or press SPACE to use your power.<small>F triggers a full Flock Fury shockwave</small>':'Drag back to aim. Release to launch.<small>Click a queued bird to change launch order</small>';if(force)updateCoach()}
